INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lofoten-skrei-cod', 'Lofoten Skrei Grounds', 'Lofoten, Nordland', 'NO', 'Saltwater', '["Atlantic cod", "Atlantic halibut", "coalfish"]'::jsonb, 'fishing-spot', true, 'Each winter the skrei — migrating Arctic cod — arrive off the Lofoten wall to spawn, in a fishery that has sustained these islands for a thousand years. Deep water lies minutes from the harbours beneath dramatic granite peaks.', '{"lat": 68.15, "lng": 13.6}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 54, "humidity": 80, "windSpeed": 16, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy jigging outfit", "Pirks and shads 200-500g", "Full flotation suit", "Braided line"], "optional": ["Charter or rorbu package", "Electric reel", "Seasickness tablets"]}'::jsonb, '["Skrei season (Jan-Apr)", "Midnight sun in summer", "Slack tide over the banks"]'::jsonb, 'Intermediate', '["Sea fishing is free in Norway — no licence required for rod and handline", "Tourists may export 15kg of fish twice a year, and only from a registered fishing camp", "Selling your catch is prohibited for recreational anglers"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('alta-river-salmon', 'Alta River', 'Alta, Finnmark', 'NO', 'Fly Fishing', '["Atlantic salmon"]'::jsonb, 'duck-spot', true, 'The most exclusive salmon river on earth, producing more twenty-kilo Atlantic salmon than anywhere else. Fished from riverboats under the midnight sun in a canyon deep in Finnmark.', '{"lat": 69.9, "lng": 23.3}'::jsonb, '{"current": 10, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 59, "humidity": 65, "windSpeed": 8, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["14-15ft Spey rod", "Large tube flies and sink tips", "Chest waders", "Insect repellent"], "optional": ["Riverboat and ghillie", "Head net for mosquitoes", "Warm layers for night fishing"]}'::jsonb, '["Peak run (Jun-Jul)", "Night fishing under midnight sun", "After a rise in water"]'::jsonb, 'Advanced', '["Norwegian national fishing fee (fiskeravgift) required for salmon, plus a local beat card", "Alta beats are allocated by lottery and largely reserved for locals — access is very limited", "Compulsory disinfection of gear brought from abroad"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('gaula-river-salmon', 'River Gaula', 'Trøndelag', 'NO', 'Fly Fishing', '["Atlantic salmon", "sea trout"]'::jsonb, 'fishing-spot', false, 'A classic big-fish salmon river south of Trondheim, with long fly-friendly runs and a strong early-season run of large multi-sea-winter fish. More accessible than Norway''s most exclusive rivers.', '{"lat": 63.1, "lng": 10.2}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 61, "humidity": 70, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["13-15ft Spey rod", "Tube flies and sink tips", "Chest waders with studs", "Wading staff"], "optional": ["Beat booking through a lodge", "Ghillie hire", "Rain gear"]}'::jsonb, '["Early run of big fish (Jun)", "Grilse (Jul-Aug)", "After rain lifts the water"]'::jsonb, 'Advanced', '["National fishing fee (fiskeravgift) plus a beat permit required", "Season and quotas are set annually and can close early", "Gear disinfection is mandatory for equipment used outside Norway"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('namsen-river-salmon', 'River Namsen', 'Namsos, Trøndelag', 'NO', 'Fly Fishing', '["Atlantic salmon", "sea trout"]'::jsonb, 'duck-spot', false, 'A wide, powerful river known as the queen of salmon rivers, traditionally fished by harling from a wooden boat. Deep holding pools produce very large fish through the summer.', '{"lat": 64.4, "lng": 11.9}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Light Rain", "temperature": 59, "humidity": 80, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy Spey or harling outfit", "Large tubes and spinners", "Chest waders", "Waterproof layers"], "optional": ["Traditional harling boat and guide", "Beat card", "Insect repellent"]}'::jsonb, '["Peak season (Jun-Jul)", "Harling in high water", "Evening and night"]'::jsonb, 'Intermediate', '["National fishing fee plus a local beat card required", "Quotas and catch reporting are mandatory", "Disinfect all gear previously used abroad before fishing"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('hardangerfjord-sea-trout', 'Hardangerfjord', 'Hordaland', 'NO', 'Saltwater', '["sea trout", "Atlantic cod", "coalfish"]'::jsonb, 'fishing-spot', false, 'Norway''s second-longest fjord, running deep between orchards and waterfalls. Sea trout patrol the shallow shorelines and river mouths, with cod and coalfish over the drop-offs.', '{"lat": 60.3, "lng": 6.2}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 61, "humidity": 80, "windSpeed": 8, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9ft spin rod or 7-weight fly rod", "Coastal spoons and shrimp flies", "Chest waders", "Polarized sunglasses"], "optional": ["Small boat hire", "Line basket", "Rain jacket"]}'::jsonb, '["Sea trout (Apr-Jun and Sep-Oct)", "Dawn along the shoreline", "Rising tide at river mouths"]'::jsonb, 'Intermediate', '["No licence needed for sea fishing, but river mouths have protection zones where fishing is banned", "Sea trout in poor condition or coloured fish must be released", "Check local rules — many fjord arms restrict fishing near salmon farms and river outlets"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('femunden-grayling', 'Lake Femunden', 'Innlandet', 'NO', 'Freshwater', '["grayling", "brown trout", "Arctic char"]'::jsonb, 'duck-spot', false, 'Norway''s third-largest lake, remote and undeveloped on the Swedish border. Grayling and wild brown trout in cold, clear water surrounded by pine forest and open fell.', '{"lat": 62.2, "lng": 11.9}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 63, "humidity": 60, "windSpeed": 10, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-6 weight fly rod or light spin", "Dry flies and small spinners", "Waders", "Insect repellent"], "optional": ["Canoe or small boat", "Camping gear", "Head net"]}'::jsonb, '["Summer (Jun-Aug)", "Evening rise", "Midnight sun in June"]'::jsonb, 'Beginner', '["A fiskekort (fishing card) is required for freshwater fishing and is sold locally or online", "Under everyman''s right you may access the shoreline, but the fishing card is still needed", "Minimum sizes and gear rules vary — check the local card conditions"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('senja-halibut', 'Senja Halibut Grounds', 'Senja, Troms', 'NO', 'Saltwater', '["Atlantic halibut", "Atlantic cod", "redfish"]'::jsonb, 'fishing-spot', false, 'Norway''s second-largest island, with steep-sided fjords and deep banks that hold very large Atlantic halibut. Serious tackle and settled weather are both essential here.', '{"lat": 69.3, "lng": 17.5}'::jsonb, '{"current": 10, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Showers", "temperature": 54, "humidity": 80, "windSpeed": 16, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy halibut outfit (150lb+)", "Large shads and gummi macks", "Flotation suit", "Circle hooks"], "optional": ["Guided boat", "Electric reel", "Release cradle for big fish"]}'::jsonb, '["Summer (Jun-Sep)", "Slack tide over the banks", "Settled weather windows"]'::jsonb, 'Advanced', '["Sea fishing is free and unlicensed in Norway", "Halibut over 2 metres must be released; a maximum size limit applies", "Export limit of 15kg twice yearly from registered camps only"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('saltstraumen-coalfish', 'Saltstraumen', 'Bodø, Nordland', 'NO', 'Saltwater', '["coalfish", "Atlantic cod", "Atlantic halibut"]'::jsonb, 'duck-spot', false, 'The strongest tidal current in the world, forcing enormous volumes of water through a narrow strait four times a day. The turbulence concentrates bait and produces huge coalfish and cod.', '{"lat": 67.23, "lng": 14.62}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 57, "humidity": 80, "windSpeed": 18, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or jigging outfit", "Pirks and large shads", "Studded boots for the shore marks", "Braided line"], "optional": ["Boat with a capable skipper", "Flotation suit", "Tide tables"]}'::jsonb, '["Around the tide change", "Summer (Jun-Sep)", "Coalfish on the running tide"]'::jsonb, 'Advanced', '["No licence required for sea angling", "The current is genuinely dangerous — only fish from a boat with an experienced local skipper", "Export and sale restrictions apply to recreational catches"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('glomma-grayling', 'River Glomma', 'Innlandet', 'NO', 'Fly Fishing', '["grayling", "brown trout", "northern pike"]'::jsonb, 'fishing-spot', false, 'Norway''s longest river, with famous grayling water in its upper reaches around Rena and Alvdal. Big, dry-fly-taking grayling rise steadily through the long northern summer evenings.', '{"lat": 61.1, "lng": 11.4}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 66, "humidity": 60, "windSpeed": 6, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-5 weight fly rod", "Dry flies and Euro nymphs", "Chest waders", "Polarized sunglasses"], "optional": ["Local fishing card", "Wading staff", "Insect repellent"]}'::jsonb, '["Summer evenings (Jun-Aug)", "Mayfly and caddis hatches", "Late-season grayling"]'::jsonb, 'Intermediate', '["A local fiskekort is required for the stretch you intend to fish", "Some sections are catch-and-release or fly-only", "Gear used abroad must be disinfected before use"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('oslofjord-sea-trout', 'Oslofjord', 'Oslo', 'NO', 'Saltwater', '["sea trout", "Atlantic cod", "mackerel"]'::jsonb, 'duck-spot', false, 'Sheltered brackish water reaching right into the capital, with rocky shorelines and shallow bays that hold sea trout year-round. Accessible fishing by public transport from central Oslo.', '{"lat": 59.6, "lng": 10.6}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 70, "humidity": 70, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9ft spin rod or 6-7 weight fly rod", "Coastal spoons and shrimp flies", "Waders", "Polarized sunglasses"], "optional": ["Line basket", "Kayak", "Warm layers for winter sessions"]}'::jsonb, '["Spring and autumn sea trout", "Winter fishing in mild spells", "Mackerel in midsummer"]'::jsonb, 'Beginner', '["Sea fishing is free and unlicensed in Norway", "River mouth protection zones prohibit fishing within set distances — check local maps", "Coloured or spawning sea trout must be released"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('vanern-salmon', 'Lake Vänern', 'Värmland', 'SE', 'Freshwater', '["landlocked salmon", "lake trout", "northern pike"]'::jsonb, 'fishing-spot', true, 'The largest lake in the European Union, holding a unique landlocked Atlantic salmon that never reaches the sea. Trolling the open water in spring produces salmon well into double figures.', '{"lat": 58.9, "lng": 13.3}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 72, "humidity": 65, "windSpeed": 12, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Trolling rods and downriggers", "Spoons and planer boards", "Sounder", "Landing net"], "optional": ["Boat with outriggers", "GPS chartplotter", "Warm layers for spring"]}'::jsonb, '["Spring salmon trolling (Apr-Jun)", "Autumn pike in the bays", "Overcast days"]'::jsonb, 'Intermediate', '["No permit needed for handheld tackle on Vänern — one of Sweden''s five great lakes with free fishing", "Salmon and trout have minimum sizes; fin-clipped and wild fish are treated differently", "Trolling rod limits apply — check the current Vänern rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('stockholm-archipelago-pike', 'Stockholm Archipelago', 'Stockholm', 'SE', 'Saltwater', '["northern pike", "perch", "zander"]'::jsonb, 'duck-spot', true, 'Thirty thousand islands of brackish Baltic water on the capital''s doorstep. Big pike hunt the shallow reed bays in spring and autumn, with perch and zander through the inner archipelago.', '{"lat": 59.3, "lng": 18.6}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 72, "humidity": 65, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo", "Large softbaits and jerkbaits", "Wire trace and unhooking mat", "Polarized sunglasses"], "optional": ["Boat or kayak hire", "Sounder", "Waterproof jacket"]}'::jsonb, '["Spring pike (Apr-May)", "Autumn (Sep-Nov)", "Calm overcast days"]'::jsonb, 'Beginner', '["Rod fishing in Swedish saltwater is free and needs no licence", "Pike and zander have minimum and maximum size limits on the east coast", "Seasonal closures protect spawning pike in some bays — check county rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('morrum-river-salmon', 'River Mörrum', 'Blekinge', 'SE', 'Fly Fishing', '["Atlantic salmon", "sea trout"]'::jsonb, 'fishing-spot', true, 'Sweden''s most famous salmon river, a short southern stream running through beech woods to the Baltic. Beats are numbered and booked by the day, and the fish run large.', '{"lat": 56.2, "lng": 14.75}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 68, "humidity": 75, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Double-handed fly rod or spin outfit", "Tube flies and spinners", "Chest waders", "Wading staff"], "optional": ["Beat booking in advance", "Landing net", "Rain jacket"]}'::jsonb, '["Spring salmon (Apr-Jun)", "Autumn sea trout (Sep-Oct)", "After rain"]'::jsonb, 'Advanced', '["A day permit for the specific beat is required and must be booked in advance", "Season dates, quotas and catch-and-release rules are set annually", "Fishing methods are restricted by beat — check the Mörrum regulations"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('vattern-char', 'Lake Vättern', 'Jönköping', 'SE', 'Freshwater', '["Arctic char", "lake trout", "whitefish"]'::jsonb, 'duck-spot', false, 'Extraordinarily clear, deep and cold, Vättern holds Arctic char left behind by the last ice age. Trolling the open water and jigging the drop-offs both produce well.', '{"lat": 58.4, "lng": 14.6}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 70, "humidity": 60, "windSpeed": 12, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Trolling or vertical jigging outfit", "Small spoons and jigs", "Sounder", "Downrigger"], "optional": ["Boat with GPS", "Warm layers", "Landing net"]}'::jsonb, '["Char (Sep-Nov)", "Spring trout trolling", "Calm mornings"]'::jsonb, 'Intermediate', '["Free handheld-tackle fishing applies on Vättern as one of the five great lakes", "Char have a closed season during autumn spawning", "Trolling rod limits and minimum sizes apply — check current rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('hjalmaren-zander', 'Lake Hjälmaren', 'Örebro', 'SE', 'Freshwater', '["zander", "northern pike", "perch"]'::jsonb, 'fishing-spot', false, 'A shallow, coloured lake that produces Sweden''s best zander fishing. Warm summer water and extensive shallow flats make it productive for both zander and big pike.', '{"lat": 59.25, "lng": 15.75}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 72, "humidity": 70, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Softbaits and jigheads", "Sounder", "Fluorocarbon leader"], "optional": ["Boat hire", "Head torch for night sessions", "Rain jacket"]}'::jsonb, '["Zander at dusk in summer", "Autumn pike", "Warm, stable weather"]'::jsonb, 'Intermediate', '["Free handheld-tackle fishing applies on Hjälmaren as one of the five great lakes", "Zander minimum size and closed season apply", "Some bays are closed during spawning — check county board rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('bohuslan-coast-mackerel', 'Bohuslän Coast', 'Västra Götaland', 'SE', 'Saltwater', '["mackerel", "Atlantic cod", "sea trout"]'::jsonb, 'duck-spot', false, 'Sweden''s rocky west coast, with saltier North Sea water than the Baltic and a scattering of granite skerries. Mackerel shoals in summer and sea trout along the shore year-round.', '{"lat": 58.4, "lng": 11.3}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 68, "humidity": 75, "windSpeed": 12, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft spin rod", "Mackerel feathers and coastal spoons", "Waders", "Windproof jacket"], "optional": ["Boat or kayak", "Line basket for fly", "Polarized sunglasses"]}'::jsonb, '["Mackerel (Jul-Sep)", "Sea trout in spring and autumn", "Calm mornings"]'::jsonb, 'Beginner', '["Rod fishing in Swedish saltwater is free and unlicensed", "Cod in the Kattegat is heavily restricted — check current limits before keeping any", "Sea trout have minimum sizes and closed seasons near river mouths"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('malaren-pike', 'Lake Mälaren', 'Stockholm / Uppsala', 'SE', 'Freshwater', '["northern pike", "zander", "perch"]'::jsonb, 'fishing-spot', false, 'Sweden''s third-largest lake, stretching west from Stockholm through a maze of bays and islands. Excellent pike and zander fishing within sight of the capital''s suburbs.', '{"lat": 59.4, "lng": 17.2}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 73, "humidity": 65, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo", "Softbaits, spinnerbaits and wire traces", "Landing net and unhooking mat", "Sounder"], "optional": ["Boat or float tube", "Polarized sunglasses", "Rain jacket"]}'::jsonb, '["Autumn pike (Sep-Nov)", "Zander at night in summer", "Spring in the shallow bays"]'::jsonb, 'Beginner', '["Free handheld-tackle fishing applies on Mälaren as one of the five great lakes", "Pike and zander minimum sizes apply", "Some areas are closed to protect spawning fish in spring"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('vindelalven-grayling', 'Vindelälven', 'Västerbotten', 'SE', 'Fly Fishing', '["grayling", "brown trout", "Atlantic salmon"]'::jsonb, 'duck-spot', false, 'One of Sweden''s four remaining free-flowing national rivers, running unimpeded from the mountains to the Baltic. Superb grayling and trout fishing in wild, lightly fished country.', '{"lat": 65.0, "lng": 18.5}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 66, "humidity": 60, "windSpeed": 8, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-6 weight fly rod", "Dry flies and nymphs", "Chest waders", "Insect repellent"], "optional": ["Local fiskekort", "Head net", "Camping gear"]}'::jsonb, '["Summer (Jun-Aug)", "Midnight sun evenings", "Mayfly hatches"]'::jsonb, 'Intermediate', '["A local fiskekort is required — everyman''s right covers access but not the fishing itself", "Salmon fishing has separate rules and quotas", "Barbless hooks and catch-and-release apply on some stretches"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('gotland-sea-trout', 'Gotland Coast', 'Gotland', 'SE', 'Saltwater', '["sea trout", "northern pike", "perch"]'::jsonb, 'fishing-spot', false, 'A limestone island in the middle of the Baltic with hundreds of kilometres of wadeable coastline. Sea trout fishing here is excellent through the cold months when the mainland freezes.', '{"lat": 57.5, "lng": 18.5}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 68, "humidity": 70, "windSpeed": 14, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft spin rod or 7-weight fly rod", "Coastal spoons and shrimp flies", "Breathable waders", "Polarized sunglasses"], "optional": ["Line basket", "Wading staff", "Thermal layers"]}'::jsonb, '["Sea trout (Oct-May)", "Onshore wind and broken water", "Mild winter days"]'::jsonb, 'Intermediate', '["Rod fishing in saltwater is free and needs no licence", "Sea trout minimum size applies and coloured fish must be released", "River mouth protection zones are closed during the autumn run"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('asnen-pike', 'Lake Åsnen', 'Småland', 'SE', 'Freshwater', '["northern pike", "perch", "common bream"]'::jsonb, 'duck-spot', false, 'A shallow, island-strewn lake in the Småland forests, now a national park. Dark, warm water grows big pike, and the surroundings are as quiet as fishing gets in southern Sweden.', '{"lat": 56.6, "lng": 14.7}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 72, "humidity": 70, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Large softbaits and spinnerbaits", "Wire trace", "Unhooking mat"], "optional": ["Canoe or small boat", "Sounder", "Insect repellent"]}'::jsonb, '["Autumn pike", "Spring after spawning", "Overcast, still days"]'::jsonb, 'Beginner', '["A fiskekort is required for Åsnen — it is not one of the five free great lakes", "National park rules restrict landing and camping in some areas", "Pike size limits and spring closures may apply — check the local card"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('saimaa-pike-zander', 'Lake Saimaa', 'South Savo', 'FI', 'Freshwater', '["northern pike", "zander", "perch"]'::jsonb, 'fishing-spot', true, 'Finland''s largest lake and one of the most convoluted lake systems on earth, with thousands of islands and endless shoreline. Zander and pike fishing is excellent, and the endangered Saimaa ringed seal lives here.', '{"lat": 61.3, "lng": 28.2}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 73, "humidity": 65, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Softbaits, jerkbaits and wire traces", "Sounder", "Landing net"], "optional": ["Boat or cottage rental", "Polarized sunglasses", "Insect repellent"]}'::jsonb, '["Zander at dusk in summer", "Autumn pike", "Ice fishing (Feb-Mar)"]'::jsonb, 'Beginner', '["Ice fishing and simple float fishing are free under everyman''s right", "Lure fishing requires the state fisheries management fee (ages 18-64) plus often a local permit", "Seasonal net and boat restrictions protect the Saimaa ringed seal"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('tornionjoki-salmon', 'Tornio River', 'Lapland', 'FI', 'Fly Fishing', '["Atlantic salmon", "grayling", "whitefish"]'::jsonb, 'duck-spot', true, 'The largest free-flowing salmon river in Europe, forming the border between Finland and Sweden. Salmon run hundreds of kilometres upstream through the long Lapland summer.', '{"lat": 66.5, "lng": 23.9}'::jsonb, '{"current": 16, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 68, "humidity": 60, "windSpeed": 8, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["13-15ft Spey rod", "Tube flies and sink tips", "Chest waders with studs", "Insect repellent"], "optional": ["Local permit and guide", "Head net for mosquitoes", "Riverboat hire"]}'::jsonb, '["Salmon run (Jun-Aug)", "Midnight sun nights", "After a rise in water"]'::jsonb, 'Advanced', '["State fisheries management fee plus a Tornio river permit required", "Season dates and daily quotas are agreed between Finland and Sweden and change yearly", "Gear disinfection is required to protect against Gyrodactylus salaris"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('inari-lake-trout', 'Lake Inari', 'Lapland', 'FI', 'Freshwater', '["brown trout", "Arctic char", "whitefish"]'::jsonb, 'fishing-spot', false, 'A vast, cold subarctic lake scattered with three thousand islands, deep in Sámi homeland. Big brown trout and Arctic char in wild, treeless country under the midnight sun.', '{"lat": 69.0, "lng": 27.9}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 61, "humidity": 60, "windSpeed": 10, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Trolling or spin outfit", "Spoons and deep divers", "Warm layers", "Sounder"], "optional": ["Boat hire or guide", "GPS — the lake is easy to get lost on", "Insect repellent"]}'::jsonb, '["Summer trolling (Jun-Aug)", "Midnight sun", "Ice fishing in spring"]'::jsonb, 'Intermediate', '["State fisheries management fee plus a regional Inari permit required", "Trout have a minimum size and there are protected spawning areas", "Respect Sámi fishing rights and local customary use"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kymijoki-river', 'River Kymijoki', 'Kymenlaakso', 'FI', 'Fly Fishing', '["brown trout", "Atlantic salmon", "grayling"]'::jsonb, 'duck-spot', false, 'A short, powerful river running to the Gulf of Finland, with rapids that hold big sea-run brown trout and salmon. Only an hour or so from Helsinki.', '{"lat": 60.7, "lng": 26.5}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 70, "humidity": 70, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-8 weight fly rod", "Streamers and nymphs", "Chest waders with studs", "Wading staff"], "optional": ["Beat permit", "Landing net", "Rain jacket"]}'::jsonb, '["Autumn run (Sep-Oct)", "Spring after ice-out", "Overcast days"]'::jsonb, 'Intermediate', '["State fisheries management fee plus a beat-specific permit required", "Most trout fishing here is catch-and-release with barbless hooks", "Water levels change quickly with hydro releases — check before wading"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('paijanne-lake', 'Lake Päijänne', 'Central Finland', 'FI', 'Freshwater', '["northern pike", "zander", "brown trout"]'::jsonb, 'fishing-spot', false, 'Finland''s second-largest lake, long, deep and clean enough to supply Helsinki''s drinking water. Good zander and pike, with stocked lake trout in the deeper basins.', '{"lat": 61.6, "lng": 25.5}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 72, "humidity": 65, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin or trolling outfit", "Softbaits and deep-diving lures", "Sounder", "Landing net"], "optional": ["Boat hire", "Downrigger", "Warm layers"]}'::jsonb, '["Summer zander", "Autumn trout trolling", "Ice fishing (Feb-Mar)"]'::jsonb, 'Beginner', '["State fisheries management fee required for lure fishing (ages 18-64)", "Ice fishing and float fishing are free under everyman''s right", "Trout minimum sizes apply; unclipped wild trout must be released"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('turku-archipelago-pike', 'Turku Archipelago', 'Southwest Finland', 'FI', 'Saltwater', '["northern pike", "perch", "sea trout"]'::jsonb, 'duck-spot', false, 'Tens of thousands of Baltic islands and skerries forming the largest archipelago in Europe by island count. Shallow brackish bays grow very large pike.', '{"lat": 60.1, "lng": 21.8}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 70, "humidity": 70, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo", "Large softbaits and wire traces", "Unhooking mat", "Polarized sunglasses"], "optional": ["Boat or kayak", "Sounder", "Waterproof jacket"]}'::jsonb, '["Spring pike (Apr-May)", "Autumn (Sep-Nov)", "Calm days in the outer skerries"]'::jsonb, 'Intermediate', '["Lure fishing in the sea requires the state fisheries management fee", "Some bays are closed in spring to protect spawning pike", "Sea trout minimum size applies and river mouth zones are protected"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ruunaa-rapids', 'Ruunaa Rapids', 'North Karelia', 'FI', 'Fly Fishing', '["brown trout", "rainbow trout", "grayling"]'::jsonb, 'fishing-spot', false, 'A chain of six rapids on the Lieksanjoki near the Russian border, managed as a hiking and fishing area. Stocked and wild trout in fast, wadeable water through pine forest.', '{"lat": 63.4, "lng": 30.5}'::jsonb, '{"current": 16, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 68, "humidity": 70, "windSpeed": 6, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-6 weight fly rod", "Streamers, nymphs and dries", "Chest waders with studs", "Insect repellent"], "optional": ["Ruunaa area permit", "Wading staff", "Camping or cabin booking"]}'::jsonb, '["Summer (Jun-Sep)", "Evening rise", "After rain"]'::jsonb, 'Intermediate', '["A Ruunaa recreational fishing permit is required in addition to the state fee", "Daily bag limits and barbless rules apply in the rapids area", "Fishing seasons vary by rapid — check the Metsähallitus rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('helsinki-coastal-zander', 'Helsinki Coast', 'Uusimaa', 'FI', 'Saltwater', '["zander", "northern pike", "perch"]'::jsonb, 'duck-spot', false, 'Brackish Baltic bays and channels right in front of the capital, productive for zander and pike. Some of the best urban fishing in the Nordics, reachable by tram and ferry.', '{"lat": 60.1, "lng": 25.0}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 70, "humidity": 75, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Softbaits and jigheads", "Head torch", "Fluorocarbon leader"], "optional": ["Kayak or small boat", "Sounder", "Waterproof jacket"]}'::jsonb, '["Zander at night in summer", "Autumn pike", "Ice fishing in the bays (Feb-Mar)"]'::jsonb, 'Beginner', '["State fisheries management fee required for lure fishing", "Ice fishing and float fishing are free under everyman''s right", "Some harbour and shipping areas are closed to angling"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kuusinkijoki-trout', 'Kuusinkijoki', 'Kuusamo, Lapland', 'FI', 'Fly Fishing', '["brown trout", "grayling"]'::jsonb, 'fishing-spot', false, 'A fast border river running east towards Russia, holding large migratory brown trout that move up from Lake Paanajärvi. Strictly managed catch-and-release water with big fish.', '{"lat": 66.2, "lng": 29.6}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 63, "humidity": 65, "windSpeed": 6, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-7 weight fly rod", "Streamers and large nymphs", "Chest waders with studs", "Insect repellent"], "optional": ["Area permit", "Wading staff", "Head net"]}'::jsonb, '["Autumn run (Aug-Sep)", "Summer evenings", "After rain"]'::jsonb, 'Advanced', '["State fisheries management fee plus a local area permit required", "Catch-and-release with barbless single hooks is mandatory on much of the river", "Border zone rules apply — carry identification"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('vuoksi-river-trout', 'River Vuoksi', 'Imatra, South Karelia', 'FI', 'Fly Fishing', '["brown trout", "landlocked salmon", "grayling"]'::jsonb, 'duck-spot', false, 'The outflow of Lake Saimaa, a big, powerful river below the Imatra rapids holding landlocked salmon and large brown trout. Heavy water that suits streamers and sink tips.', '{"lat": 61.2, "lng": 28.8}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 70, "humidity": 70, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["7-8 weight fly rod", "Streamers and sink tips", "Chest waders with studs", "Wading staff"], "optional": ["Beat permit", "Boat for the deeper runs", "Rain jacket"]}'::jsonb, '["Autumn (Sep-Oct)", "Spring after ice-out", "Overcast days"]'::jsonb, 'Advanced', '["State fisheries management fee plus a local permit required", "Saimaa landlocked salmon is critically endangered and must be released", "Hydro releases change levels rapidly — check flows before wading"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('cape-point-yellowtail', 'Cape Point & False Bay', 'Cape Town, Western Cape', 'ZA', 'Saltwater', '["yellowtail", "snoek", "yellowfin tuna"]'::jsonb, 'fishing-spot', true, 'Cold, nutrient-rich Atlantic water meets the warmer Indian Ocean off the Cape Peninsula, making it one of the richest inshore fisheries anywhere. Yellowtail on the pinnacles and yellowfin tuna a short run offshore.', '{"lat": -34.3, "lng": 18.5}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 61, "humidity": 75, "windSpeed": 20, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or jigging outfit", "Spinning jigs and live bait", "Foul weather gear", "Fluorocarbon leader"], "optional": ["Charter booking", "Sounder", "Seasickness tablets"]}'::jsonb, '["Yellowtail (Nov-Apr)", "Tuna year-round in settled weather", "Early morning before the wind"]'::jsonb, 'Advanced', '["A recreational fishing permit is required and can now be bought online through the DFFE portal", "Daily bag and size limits apply per species", "Large parts of False Bay and the Table Mountain MPA are no-take zones"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('sodwana-bay', 'Sodwana Bay', 'KwaZulu-Natal', 'ZA', 'Saltwater', '["king mackerel", "giant trevally", "sailfish"]'::jsonb, 'duck-spot', true, 'Warm Agulhas current water over the southernmost coral reefs in Africa, inside the iSimangaliso Wetland Park. Couta, gamefish and billfish all within a short run of the beach launch.', '{"lat": -27.5, "lng": 32.7}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 75, "humidity": 70, "windSpeed": 12, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy trolling or spin outfit", "Rapalas, live bait and wire traces", "Sun protection", "Braided line"], "optional": ["Ski-boat charter", "Outriggers", "Dive gear for the reefs"]}'::jsonb, '["Couta season (Apr-Sep)", "Gamefish in summer", "Calm mornings"]'::jsonb, 'Intermediate', '["DFFE recreational fishing permit required", "iSimangaliso is a World Heritage Site — launch sites and no-take zones are strictly controlled", "Species size and bag limits apply; some reef fish are fully protected"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('orange-river-yellowfish', 'Orange River', 'Upington, Northern Cape', 'ZA', 'Fly Fishing', '["largemouth yellowfish", "smallmouth yellowfish"]'::jsonb, 'fishing-spot', false, 'South Africa''s longest river cutting through arid Northern Cape country. Largemouth yellowfish take big streamers in the rapids, and the setting is pure desert wilderness.', '{"lat": -28.6, "lng": 20.5}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 72, "humidity": 30, "windSpeed": 8, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-8 weight fly rod", "Large streamers and nymphs", "Wading boots", "Sun protection"], "optional": ["Guided drift or raft trip", "Polarized sunglasses", "Plenty of water"]}'::jsonb, '["Autumn (Mar-May)", "Spring (Sep-Nov)", "Low, clear water"]'::jsonb, 'Advanced', '["Freshwater angling permits are issued at provincial level — check Northern Cape requirements", "Yellowfish are catch-and-release by convention and often by rule", "Access is largely through private land or licensed outfitters"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('vaal-river-yellowfish', 'Vaal River', 'Parys, Free State', 'ZA', 'Fly Fishing', '["smallmouth yellowfish", "largemouth yellowfish", "carp"]'::jsonb, 'duck-spot', false, 'The closest quality fly water to Johannesburg, with wide shallow rapids holding hard-fighting smallmouth yellowfish. Wade the pocket water with nymphs on light tackle.', '{"lat": -26.9, "lng": 27.5}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 68, "humidity": 40, "windSpeed": 10, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-6 weight fly rod", "Czech nymphs and small streamers", "Wading boots with studs", "Polarized sunglasses"], "optional": ["Guide or lodge day rate", "Wading staff", "Sun protection"]}'::jsonb, '["Autumn (Mar-May)", "Summer after floods clear", "Warm afternoons in winter"]'::jsonb, 'Intermediate', '["A Free State or Gauteng angling licence is required depending on the bank", "Yellowfish are catch-and-release on most managed stretches", "Most access is via private farms or lodges — arrange permission first"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('transkei-wild-coast', 'Wild Coast', 'Transkei, Eastern Cape', 'ZA', 'Saltwater', '["dusky kob", "garrick", "shad"]'::jsonb, 'fishing-spot', false, 'A remote, undeveloped coastline of rocky points and river mouths between Durban and East London. Kob and garrick move through on the sardine run, and the beaches are often empty.', '{"lat": -32.0, "lng": 28.9}'::jsonb, '{"current": 19, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 70, "humidity": 75, "windSpeed": 14, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["12-13ft surf rod", "Sliding trace rigs and live bait", "Studded boots for the rocks", "Head torch"], "optional": ["4WD for beach access", "Rod holder", "Cool box"]}'::jsonb, '["Sardine run (Jun-Jul)", "Garrick in spring", "Dawn and dusk on the points"]'::jsonb, 'Intermediate', '["DFFE recreational fishing permit required", "Dusky kob has strict size and bag limits and is under pressure — check current rules", "Rock and surf conditions can be dangerous; several MPAs along this coast are closed"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('durban-deep-sea', 'Durban Deep Sea', 'Durban, KwaZulu-Natal', 'ZA', 'Saltwater', '["king mackerel", "yellowfin tuna", "black marlin"]'::jsonb, 'duck-spot', false, 'The continental shelf drops away close to Durban, putting gamefish and billfish within an hour of the harbour. Couta in winter and marlin through the warmer months.', '{"lat": -29.9, "lng": 31.2}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 75, "humidity": 80, "windSpeed": 12, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy trolling outfit", "Konas, rapalas and live bait", "Wire traces", "Sun protection"], "optional": ["Charter or ski-boat", "Outriggers", "Seasickness tablets"]}'::jsonb, '["Couta (May-Sep)", "Marlin (Nov-Mar)", "Sardine run in winter"]'::jsonb, 'Advanced', '["DFFE recreational fishing permit required", "Billfish are largely tag-and-release in South Africa", "Bag limits apply per species; check current DFFE tables"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('sterkfontein-dam', 'Sterkfontein Dam', 'Free State', 'ZA', 'Fly Fishing', '["smallmouth yellowfish"]'::jsonb, 'fishing-spot', false, 'A vast, gin-clear highland dam in the Drakensberg foothills, dedicated almost entirely to sight fishing for smallmouth yellowfish. Often described as Africa''s answer to bonefishing.', '{"lat": -28.4, "lng": 29.0}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 66, "humidity": 45, "windSpeed": 12, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-6 weight fly rod", "Small hoppers and nymphs", "Wading boots", "Polarized sunglasses"], "optional": ["Float tube or boat", "Sun protection", "Long fine leader"]}'::jsonb, '["Summer (Nov-Mar)", "Calm, bright days for sight fishing", "Early morning shorelines"]'::jsonb, 'Advanced', '["Free State angling licence required, plus a Sterkfontein Dam Nature Reserve permit", "Catch-and-release is the norm and is enforced in the reserve", "Barbless hooks are recommended and required in places"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('dullstroom-trout', 'Dullstroom', 'Mpumalanga', 'ZA', 'Fly Fishing', '["rainbow trout", "brown trout"]'::jsonb, 'duck-spot', false, 'South Africa''s trout capital, a cool highland town two hours from Johannesburg surrounded by stocked stillwaters and small streams. The country''s most accessible trout fishing.', '{"lat": -25.4, "lng": 30.1}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Cold and Clear", "temperature": 57, "humidity": 55, "windSpeed": 10, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-6 weight fly rod", "Woolly buggers and nymphs", "Warm layers", "Landing net"], "optional": ["Day ticket from a lodge", "Float tube", "Waders"]}'::jsonb, '["Winter (May-Aug) for cold water", "Overcast days", "Early morning and evening"]'::jsonb, 'Beginner', '["Mpumalanga angling licence required for public water", "Almost all stillwaters here are private — a day ticket from the lodge or farm is needed", "Many venues are catch-and-release with barbless hooks"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('west-coast-snoek', 'West Coast Snoek Grounds', 'Saldanha, Western Cape', 'ZA', 'Saltwater', '["snoek", "hottentot", "yellowtail"]'::jsonb, 'fishing-spot', false, 'Cold Benguela current water running up the west coast, driving huge shoals of snoek within reach of the small fishing harbours. A rough, traditional and highly productive fishery.', '{"lat": -33.0, "lng": 17.9}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 59, "humidity": 75, "windSpeed": 22, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy boat rod", "Snoek lures and handlines", "Wet weather gear", "Wire trace"], "optional": ["Local skipper or charter", "Cool box", "Gloves — snoek have serious teeth"]}'::jsonb, '["Winter snoek run (May-Aug)", "Calm mornings before the southeaster", "Overcast days"]'::jsonb, 'Intermediate', '["DFFE recreational fishing permit required", "Daily bag limits apply to snoek and yellowtail", "Sea conditions on this coast change fast — check the forecast before launching"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('jozini-tigerfish', 'Jozini Dam', 'Pongolapoort, KwaZulu-Natal', 'ZA', 'Freshwater', '["tigerfish", "tilapia"]'::jsonb, 'duck-spot', false, 'The only place in South Africa where you can reliably catch tigerfish, in a large dam beneath the Lebombo mountains. Aggressive strikes and hard fighting in warm, wild country.', '{"lat": -27.4, "lng": 32.1}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 79, "humidity": 55, "windSpeed": 8, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin or 8-weight fly rod", "Spoons, rapalas and wire traces", "Sharp hooks — tigerfish jaws are bony", "Sun protection"], "optional": ["Boat or houseboat charter", "Sounder", "Insect repellent"]}'::jsonb, '["Summer (Oct-Apr)", "Early morning and late afternoon", "Warm, stable weather"]'::jsonb, 'Intermediate', '["KwaZulu-Natal freshwater angling licence required", "Tigerfish are usually catch-and-release; handle with care", "Crocodiles and hippos are present — do not wade or swim"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-grande-sea-trout', 'Río Grande', 'Tierra del Fuego', 'AR', 'Fly Fishing', '["sea-run brown trout"]'::jsonb, 'fishing-spot', true, 'The finest sea-run brown trout river on earth, running across the windswept Fuegian steppe to the South Atlantic. Double-figure fish are routine and twenty-pounders are a genuine possibility.', '{"lat": -53.8, "lng": -67.7}'::jsonb, '{"current": 6, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 39, "humidity": 70, "windSpeed": 30, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-9 weight single or switch rod", "Sink tips and leeches", "Chest waders", "Windproof layers"], "optional": ["Lodge booking with guide", "Wading staff", "Head net for the wind"]}'::jsonb, '["Peak run (Jan-Mar)", "Evening and night sessions", "When the wind eases"]'::jsonb, 'Advanced', '["A Tierra del Fuego provincial fishing licence is required", "Season runs roughly November to mid-April; access is almost entirely through private lodges", "Catch-and-release with barbless hooks is mandatory"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('jurassic-lake-strobel', 'Jurassic Lake', 'Lago Strobel, Santa Cruz', 'AR', 'Fly Fishing', '["rainbow trout"]'::jsonb, 'duck-spot', true, 'A remote alkaline lake on the Patagonian steppe with no natural predators and vast scud populations, growing rainbow trout to extraordinary sizes. Ten-pound fish are considered average here.', '{"lat": -48.6, "lng": -71.2}'::jsonb, '{"current": 7, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 41, "humidity": 50, "windSpeed": 35, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["7-8 weight fly rod", "Scud patterns and large streamers", "Chest waders", "Serious windproof clothing"], "optional": ["Lodge package — the lake is extremely remote", "Backup rod", "Sun protection"]}'::jsonb, '["Season (Nov-Apr)", "Calmer mornings", "Overcast days"]'::jsonb, 'Advanced', '["Santa Cruz provincial fishing licence required", "Access is via private lodges only; there are no public roads or facilities", "Catch-and-release with barbless hooks is enforced"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('parana-river-dorado', 'Paraná River', 'Paso de la Patria, Corrientes', 'AR', 'Freshwater', '["golden dorado", "surubí", "pacú"]'::jsonb, 'fishing-spot', true, 'South America''s second-largest river, home to the golden dorado — a hard-jumping, gold-flanked predator that has become a bucket-list fly rod species. Big surubí catfish share the same water.', '{"lat": -27.3, "lng": -58.6}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 73, "humidity": 75, "windSpeed": 8, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-9 weight fly rod or medium baitcast", "Large streamers and wire bite guards", "Sharp hooks — dorado jaws are hard", "Sun protection"], "optional": ["Guided boat", "Insect repellent", "Polarized sunglasses"]}'::jsonb, '["Dorado (Sep-Apr)", "Low, clear water", "Early morning"]'::jsonb, 'Intermediate', '["A Corrientes provincial fishing licence is required", "Dorado is catch-and-release in many provinces and has closed seasons — check current rules", "Fish through licensed guides; some stretches are closed to protect spawning fish"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-limay-trout', 'Río Limay', 'Neuquén', 'AR', 'Fly Fishing', '["brown trout", "rainbow trout"]'::jsonb, 'duck-spot', false, 'A big, cold tailwater running out of Nahuel Huapi through the Patagonian steppe. Large browns hold along the willow banks and in the deep runs, best fished from a drift boat.', '{"lat": -39.9, "lng": -70.9}'::jsonb, '{"current": 8, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 45, "humidity": 50, "windSpeed": 25, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-7 weight fly rod", "Large streamers and dry-dropper rigs", "Chest waders", "Windproof jacket"], "optional": ["Drift boat and guide", "Wading staff", "Polarized sunglasses"]}'::jsonb, '["Season (Nov-Apr)", "Early and late in the day", "Overcast, less windy days"]'::jsonb, 'Intermediate', '["Neuquén provincial licence required; a national parks licence is needed inside park boundaries", "Season runs roughly mid-November to mid-April", "Barbless hooks and catch-and-release apply on many stretches"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('nahuel-huapi-trout', 'Lago Nahuel Huapi', 'Bariloche, Río Negro', 'AR', 'Freshwater', '["brown trout", "rainbow trout", "brook trout"]'::jsonb, 'fishing-spot', false, 'A deep glacial lake in the heart of the Argentine Lake District, ringed by Andean peaks. Trolling the drop-offs and casting the stream mouths both produce large trout.', '{"lat": -41.0, "lng": -71.5}'::jsonb, '{"current": 8, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 45, "humidity": 55, "windSpeed": 18, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-7 weight fly rod or trolling outfit", "Streamers and spoons", "Warm layers", "Landing net"], "optional": ["Boat hire or guide", "Downrigger", "Polarized sunglasses"]}'::jsonb, '["Season (Nov-Apr)", "Dawn at the stream mouths", "Calm mornings"]'::jsonb, 'Beginner', '["Nahuel Huapi National Park licence required — separate from the provincial licence", "Season dates are set annually by the park administration", "Catch-and-release and barbless rules apply in much of the park"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-chimehuin', 'Río Chimehuín', 'Junín de los Andes, Neuquén', 'AR', 'Fly Fishing', '["brown trout", "rainbow trout"]'::jsonb, 'duck-spot', false, 'A classic freestone river running out of Lago Huechulafquen, famous since the 1950s for very large brown trout. The boca at the lake outlet is one of Patagonia''s most storied pools.', '{"lat": -39.9, "lng": -71.1}'::jsonb, '{"current": 9, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 48, "humidity": 50, "windSpeed": 20, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-7 weight fly rod", "Streamers, hoppers and nymphs", "Chest waders", "Windproof jacket"], "optional": ["Guide hire", "Wading staff", "Sun protection"]}'::jsonb, '["Season opening (Nov)", "Hopper season (Jan-Feb)", "Evening at the boca"]'::jsonb, 'Intermediate', '["Neuquén provincial licence required; a Lanín National Park licence covers the upper river", "Season runs roughly November to April", "Barbless hooks required in national park water"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-gallegos-sea-trout', 'Río Gallegos', 'Santa Cruz', 'AR', 'Fly Fishing', '["sea-run brown trout"]'::jsonb, 'fishing-spot', false, 'A smaller, more intimate sea trout river than the Río Grande, winding through open Santa Cruz sheep country. Fish here average less but the fishing is technical and rewarding.', '{"lat": -51.6, "lng": -69.2}'::jsonb, '{"current": 6, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 39, "humidity": 65, "windSpeed": 30, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["7-8 weight single-handed rod", "Small streamers and nymphs", "Chest waders", "Windproof layers"], "optional": ["Lodge booking", "Wading staff", "Head net"]}'::jsonb, '["Peak run (Jan-Mar)", "Evening sessions", "Lulls in the wind"]'::jsonb, 'Advanced', '["Santa Cruz provincial licence required", "Access is mostly through private estancias and lodges", "Catch-and-release with barbless hooks is standard"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('mar-del-plata-offshore', 'Mar del Plata Offshore', 'Buenos Aires Province', 'AR', 'Saltwater', '["black drum", "white croaker", "sea bass"]'::jsonb, 'duck-spot', false, 'Argentina''s main fishing port, with a productive shelf and a long tradition of shore and boat angling. Big black drum around the harbour walls and croaker over the sand.', '{"lat": -38.05, "lng": -57.5}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 52, "humidity": 75, "windSpeed": 18, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Surf or boat rod", "Bait rigs with squid and shrimp", "Waterproof jacket", "Rod holder"], "optional": ["Charter booking", "Head torch", "Cool box"]}'::jsonb, '["Black drum (Nov-Feb)", "Croaker in summer", "Calm days after a storm"]'::jsonb, 'Beginner', '["No licence is required for sea fishing in most Argentine coastal provinces", "Size and bag limits apply to some species — check provincial rules", "Port and harbour areas have restricted access"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('peninsula-valdes-shore', 'Península Valdés', 'Chubut', 'AR', 'Saltwater', '["Argentine sea bass", "sharks", "silverside"]'::jsonb, 'fishing-spot', false, 'A UNESCO-listed peninsula of gravel beaches and cliffs on the Patagonian Atlantic coast. Shore fishing among sea lions and whales, in one of Argentina''s great wildlife landscapes.', '{"lat": -42.5, "lng": -64.3}'::jsonb, '{"current": 10, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 48, "humidity": 65, "windSpeed": 25, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Surf rod", "Grip leads and bait rigs", "Windproof clothing", "Rod holder"], "optional": ["4WD for beach tracks", "Cool box", "Binoculars for whale watching"]}'::jsonb, '["Summer (Dec-Mar)", "Rising tide", "Sheltered bays on windy days"]'::jsonb, 'Intermediate', '["Chubut provincial rules apply; a permit may be needed for the protected area", "Península Valdés is a nature reserve — access, driving and fishing zones are controlled", "Keep well clear of marine mammal colonies"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('embalse-rio-tercero', 'Embalse Río Tercero', 'Córdoba', 'AR', 'Freshwater', '["silverside", "largemouth bass", "carp"]'::jsonb, 'duck-spot', false, 'Córdoba''s largest reservoir, a popular inland fishery for pejerrey silverside and introduced largemouth bass. Easy access and gentle conditions compared with Patagonia.', '{"lat": -32.2, "lng": -64.4}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 63, "humidity": 50, "windSpeed": 12, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Light spin or float rod", "Small jigs, spinners and live bait", "Landing net", "Sun protection"], "optional": ["Boat hire", "Sounder", "Cool box"]}'::jsonb, '["Pejerrey in winter (Jun-Sep)", "Bass in summer", "Early morning"]'::jsonb, 'Beginner', '["Córdoba provincial fishing licence required", "Size and bag limits apply, and some species have closed seasons", "Boat registration rules apply on the reservoir"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-negro-peacock-bass', 'Rio Negro', 'Amazonas', 'BR', 'Freshwater', '["peacock bass", "arowana", "piranha"]'::jsonb, 'fishing-spot', true, 'Black water flowing through flooded Amazon forest, holding the largest peacock bass in the world. Fished from mothership operations during the dry season when the fish concentrate in the lagoons.', '{"lat": -1.4, "lng": -62.0}'::jsonb, '{"current": 29, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 90, "humidity": 85, "windSpeed": 5, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy baitcast combo (65lb braid)", "Large topwater props and jigs", "Heavy fluorocarbon leader", "Sun protection and long sleeves"], "optional": ["Mothership or lodge package", "Insect repellent", "Backup rods — peacock bass destroy tackle"]}'::jsonb, '["Dry season (Sep-Mar)", "Low water in the lagoons", "Early morning topwater"]'::jsonb, 'Advanced', '["A federal licença de pesca amadora is required and is valid nationwide for one year", "Federal quota is 10kg plus one specimen for inland waters; states may set stricter limits", "Indigenous territories require separate permission — fish through licensed operators"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('pantanal-dorado', 'Pantanal Wetlands', 'Mato Grosso do Sul', 'BR', 'Freshwater', '["golden dorado", "pacú", "pintado catfish"]'::jsonb, 'duck-spot', true, 'The world''s largest tropical wetland, laced with clear rivers running into the Paraguay basin. Golden dorado, pacú and huge pintado catfish, with extraordinary wildlife on every bank.', '{"lat": -19.0, "lng": -57.0}'::jsonb, '{"current": 24, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 84, "humidity": 70, "windSpeed": 6, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy baitcast or 8-weight fly rod", "Streamers, topwaters and wire traces", "Sun protection", "Sharp hooks"], "optional": ["Guided boat or lodge", "Insect repellent", "Binoculars"]}'::jsonb, '["Dry season (Jun-Oct)", "Low, clear water", "Dawn and dusk"]'::jsonb, 'Intermediate', '["Federal licença de pesca amadora required", "Piracema spawning closure typically runs November to February — fishing is banned or restricted", "Dorado is protected in some states — check Mato Grosso do Sul rules before keeping fish"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('agua-boa-peacock-bass', 'Agua Boa River', 'Roraima', 'BR', 'Fly Fishing', '["peacock bass", "arowana", "payara"]'::jsonb, 'fishing-spot', false, 'A rare clear-water Amazon tributary where peacock bass can be sight fished on the fly over white sand flats. Considered the premier fly fishing destination in the Amazon basin.', '{"lat": 1.5, "lng": -61.5}'::jsonb, '{"current": 29, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 90, "humidity": 85, "windSpeed": 5, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10 weight fly rod", "Large baitfish flies and poppers", "Heavy shock tippet", "Sun protection"], "optional": ["Lodge package with guide", "Stripping basket", "Insect repellent"]}'::jsonb, '["Dry season (Nov-Mar)", "Clear low water", "Bright days for sight fishing"]'::jsonb, 'Advanced', '["Federal licença de pesca amadora required", "This river is managed as catch-and-release fly water through a single licensed lodge", "Indigenous land boundaries apply — access is only through the authorised operator"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-xingu-payara', 'Rio Xingu', 'Pará', 'BR', 'Freshwater', '["payara", "peacock bass", "pacú"]'::jsonb, 'duck-spot', false, 'A powerful clear-water Amazon tributary with rapids and rocky channels holding payara — the fanged vampire fish. Hard fighting in fast, technical water.', '{"lat": -3.2, "lng": -52.2}'::jsonb, '{"current": 28, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 90, "humidity": 80, "windSpeed": 5, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or baitcast outfit", "Jigs, spoons and wire traces", "Very sharp hooks", "Sun protection"], "optional": ["Guided boat", "Insect repellent", "Polarized sunglasses"]}'::jsonb, '["Dry season (Jul-Nov)", "Rapids and channel edges", "Early morning"]'::jsonb, 'Advanced', '["Federal licença de pesca amadora required", "Piracema closed season applies — usually November to February", "Large stretches border indigenous territory; go through licensed guides only"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('cabo-frio-offshore', 'Cabo Frio', 'Rio de Janeiro', 'BR', 'Saltwater', '["dolphinfish", "yellowfin tuna", "amberjack"]'::jsonb, 'fishing-spot', false, 'An upwelling of cold water off Cabo Frio makes this one of the richest stretches of the Brazilian coast. Dorado, tuna and amberjack over the offshore banks and wrecks.', '{"lat": -22.9, "lng": -41.9}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 75, "humidity": 70, "windSpeed": 14, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin or trolling outfit", "Jigs, poppers and trolling lures", "Fluorocarbon leader", "Sun protection"], "optional": ["Charter booking", "Sounder", "Seasickness tablets"]}'::jsonb, '["Summer (Dec-Mar)", "After the upwelling settles", "Calm mornings"]'::jsonb, 'Intermediate', '["Federal licença de pesca amadora required for marine recreational fishing", "Marine quota is 15kg plus one specimen per angler", "Some species including groupers have closed seasons — check IBAMA rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('vitoria-marlin', 'Vitória Offshore', 'Espírito Santo', 'BR', 'Saltwater', '["blue marlin", "sailfish", "wahoo"]'::jsonb, 'duck-spot', false, 'The Vitória-Trindade seamount chain runs east from the coast here, creating outstanding billfish grounds. Blue marlin and sailfish over the banks in warm blue water.', '{"lat": -20.3, "lng": -40.2}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 81, "humidity": 75, "windSpeed": 12, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy trolling outfit (50-80lb)", "Skirted lures and rigged baits", "Fighting harness", "Sun protection"], "optional": ["Charter booking", "Outriggers", "Camera"]}'::jsonb, '["Billfish (Oct-Mar)", "Calm weather windows", "Full moon periods"]'::jsonb, 'Advanced', '["Federal licença de pesca amadora required", "Billfish are released under Brazilian sport fishing convention", "Marine bag quota applies to retained species"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-sao-francisco', 'Rio São Francisco', 'Bahia / Minas Gerais', 'BR', 'Freshwater', '["surubim catfish", "dourado", "tucunaré"]'::jsonb, 'fishing-spot', false, 'Brazil''s great inland river, running north through the semi-arid sertão. Big surubim catfish and dourado, with peacock bass established in the reservoirs along its length.', '{"lat": -9.4, "lng": -38.2}'::jsonb, '{"current": 26, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 88, "humidity": 55, "windSpeed": 8, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy baitcast outfit", "Large plugs, jigs and live bait", "Heavy leader", "Sun protection"], "optional": ["Boat and local guide", "Insect repellent", "Cool box"]}'::jsonb, '["Dry season (Jun-Oct)", "Dawn and dusk", "Below the dams"]'::jsonb, 'Intermediate', '["Federal licença de pesca amadora required", "Piracema closure runs roughly November to February on this river", "Minimum sizes apply to surubim and dourado — check state rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ilhabela-sao-paulo', 'Ilhabela', 'São Paulo', 'BR', 'Saltwater', '["amberjack", "snook", "dolphinfish"]'::jsonb, 'duck-spot', false, 'A mountainous island off the São Paulo coast with rocky points, wrecks and deep channels. Amberjack over the structure and snook along the mangrove-fringed shoreline.', '{"lat": -23.8, "lng": -45.4}'::jsonb, '{"current": 23, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 79, "humidity": 80, "windSpeed": 10, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin or jigging outfit", "Vertical jigs and soft plastics", "Fluorocarbon leader", "Sun protection"], "optional": ["Boat or charter", "Sounder", "Polarized sunglasses"]}'::jsonb, '["Summer (Dec-Mar)", "Snook around the mangroves at dawn", "Calm days"]'::jsonb, 'Intermediate', '["Federal licença de pesca amadora required", "Snook has a closed season and minimum size in São Paulo state", "Marine protected areas around the island restrict fishing — check zoning"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-araguaia', 'Rio Araguaia', 'Tocantins', 'BR', 'Freshwater', '["peacock bass", "piranha", "pacú"]'::jsonb, 'fishing-spot', false, 'A long clear river with vast seasonal sand beaches that emerge in the dry season. Peacock bass in the lagoons and backwaters, and a strong local camping and fishing culture.', '{"lat": -12.0, "lng": -50.6}'::jsonb, '{"current": 28, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 90, "humidity": 60, "windSpeed": 6, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium baitcast combo", "Topwaters, jigs and spoons", "Wire or heavy fluoro leader", "Sun protection"], "optional": ["Boat and guide", "Camping gear for the beaches", "Insect repellent"]}'::jsonb, '["Dry season (Jun-Sep)", "Beach camping season (Jul)", "Early morning"]'::jsonb, 'Beginner', '["Federal licença de pesca amadora required", "Piracema closure applies from around November to February", "Pirarucu is protected and may not be taken without specific authorisation"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lagoa-dos-patos', 'Lagoa dos Patos', 'Rio Grande do Sul', 'BR', 'Freshwater', '["traíra", "whitemouth croaker", "common carp"]'::jsonb, 'duck-spot', false, 'The largest lagoon in South America, brackish at its southern end where it meets the Atlantic. Croaker run in from the sea, and traíra hold in the reedy freshwater margins.', '{"lat": -31.0, "lng": -51.3}'::jsonb, '{"current": 16, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 64, "humidity": 75, "windSpeed": 18, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin or surf rod", "Soft plastics and bait rigs", "Waterproof jacket", "Landing net"], "optional": ["Small boat", "Rod holder", "Cool box"]}'::jsonb, '["Croaker run (Apr-Jun)", "Traíra in summer", "After onshore winds"]'::jsonb, 'Beginner', '["Federal licença de pesca amadora required", "Rio Grande do Sul sets additional local quotas and closed seasons", "Croaker has a minimum size — check state rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('cabo-san-lucas-marlin', 'Cabo San Lucas', 'Baja California Sur', 'MX', 'Saltwater', '["striped marlin", "dolphinfish", "yellowfin tuna"]'::jsonb, 'fishing-spot', true, 'The marlin capital of the world, where the Pacific meets the Sea of Cortez at the tip of Baja. Striped marlin are available year-round within a short run of the harbour.', '{"lat": 22.88, "lng": -109.9}'::jsonb, '{"current": 28, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 90, "humidity": 65, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy trolling outfit (30-50lb)", "Skirted lures and live bait", "Fighting belt", "Sun protection"], "optional": ["Charter booking", "Outriggers", "Seasickness tablets"]}'::jsonb, '["Striped marlin (Oct-Jun)", "Tuna and dorado in summer", "Early morning"]'::jsonb, 'Intermediate', '["Every person aboard a fishing vessel in Mexican waters needs a CONAPESCA licence, whether fishing or not", "No licence is required when fishing from shore", "Billfish are limited to one per day and may not be sold — most are released"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('la-paz-roosterfish', 'La Paz & Espíritu Santo', 'Baja California Sur', 'MX', 'Saltwater', '["roosterfish", "dolphinfish", "yellowtail"]'::jsonb, 'duck-spot', true, 'Clear Sea of Cortez water around Isla Espíritu Santo, with roosterfish cruising the beaches and sand drop-offs. One of the best places anywhere to sight fish for roosters.', '{"lat": 24.15, "lng": -110.3}'::jsonb, '{"current": 28, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 95, "humidity": 60, "windSpeed": 8, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin or 10-weight fly rod", "Poppers and large baitfish flies", "Fluorocarbon leader", "Sun protection"], "optional": ["Panga and guide", "Stripping basket", "Polarized sunglasses"]}'::jsonb, '["Roosterfish (May-Oct)", "Dawn along the beaches", "Calm mornings"]'::jsonb, 'Advanced', '["CONAPESCA licence required for everyone aboard a vessel", "Roosterfish are catch-and-release only in Mexico and may not be commercially taken", "Espíritu Santo is a national park with protected zones"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ascension-bay-bonefish', 'Ascension Bay', 'Quintana Roo', 'MX', 'Saltwater', '["bonefish", "permit", "tarpon"]'::jsonb, 'fishing-spot', true, 'A vast shallow flats system inside the Sian Ka''an Biosphere Reserve, offering the Caribbean grand slam of bonefish, permit and tarpon. Wadeable turtle grass and white sand for miles.', '{"lat": 19.7, "lng": -87.5}'::jsonb, '{"current": 29, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 90, "humidity": 80, "windSpeed": 14, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-10 weight fly rod", "Crab and shrimp patterns", "Flats boots", "Polarized sunglasses"], "optional": ["Lodge and guide package", "Stripping basket", "Sun hoodie and gloves"]}'::jsonb, '["Permit year-round", "Tarpon (Mar-Sep)", "Calm bright mornings"]'::jsonb, 'Advanced', '["CONAPESCA licence required when fishing from a boat", "Sian Ka''an is a UNESCO biosphere reserve — fishing is catch-and-release through licensed guides", "Access is controlled; independent fishing in the reserve is restricted"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('isla-mujeres-sailfish', 'Isla Mujeres', 'Quintana Roo', 'MX', 'Saltwater', '["sailfish", "dolphinfish", "wahoo"]'::jsonb, 'duck-spot', false, 'Each winter huge numbers of sailfish gather off Isla Mujeres to feed on migrating sardine balls. One of the most spectacular billfish concentrations on the planet.', '{"lat": 21.25, "lng": -86.7}'::jsonb, '{"current": 28, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 86, "humidity": 75, "windSpeed": 14, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["20-30lb spin or conventional outfit", "Live bait and teasers", "Fighting belt", "Sun protection"], "optional": ["Charter booking", "Snorkel gear for the bait balls", "Camera"]}'::jsonb, '["Sailfish run (Jan-Mar)", "Calm mornings", "Following the frigate birds"]'::jsonb, 'Intermediate', '["CONAPESCA licence required for all aboard", "Sailfish are limited and released under Mexican sport fishing norms", "Nearby marine parks have no-take zones — check with the operator"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-el-salto-bass', 'Lake El Salto', 'Sinaloa', 'MX', 'Freshwater', '["largemouth bass", "tilapia"]'::jsonb, 'fishing-spot', false, 'A tropical Mexican reservoir famous for trophy largemouth bass, with abundant tilapia forage growing fish to double figures. Standing timber and rocky points hold fish year-round.', '{"lat": 23.8, "lng": -106.4}'::jsonb, '{"current": 28, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 95, "humidity": 60, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy baitcast combo", "Crankbaits, jigs and soft plastics", "Fluorocarbon leader", "Sun protection"], "optional": ["Lodge package with panga guide", "Sounder", "Wide-brimmed hat"]}'::jsonb, '["Pre-spawn (Jan-Mar)", "Autumn (Oct-Nov)", "Dawn topwater"]'::jsonb, 'Beginner', '["A CONAPESCA sport fishing licence covers freshwater as well as marine angling", "Most lodges arrange licences for guests", "Catch-and-release is the norm for trophy bass at these lakes"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-baccarac-bass', 'Lake Baccarac', 'Sinaloa', 'MX', 'Freshwater', '["largemouth bass", "tilapia"]'::jsonb, 'duck-spot', false, 'A remote Sinaloa reservoir in the Sierra Madre foothills with a long reputation for producing genuine trophy largemouth bass. Steep rocky banks and flooded timber.', '{"lat": 26.8, "lng": -108.1}'::jsonb, '{"current": 27, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 93, "humidity": 55, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy baitcast combo", "Big swimbaits and jigs", "Heavy fluorocarbon", "Sun protection"], "optional": ["Lodge package", "Sounder", "Cool box"]}'::jsonb, '["Winter and spring (Dec-Apr)", "Falling water levels", "Early morning"]'::jsonb, 'Intermediate', '["CONAPESCA sport fishing licence required", "Lodges typically handle licensing and transport from Los Mochis", "Trophy bass are released under lodge policy"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('puerto-vallarta-marlin', 'Corbeteña & El Banco', 'Puerto Vallarta, Jalisco', 'MX', 'Saltwater', '["black marlin", "yellowfin tuna", "dolphinfish"]'::jsonb, 'fishing-spot', false, 'Two offshore seamounts west of Banderas Bay that rise from deep water and hold enormous tuna and black marlin. Long runs offshore for genuinely large fish.', '{"lat": 20.75, "lng": -105.9}'::jsonb, '{"current": 28, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 90, "humidity": 75, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy trolling outfit (80-130lb)", "Skirted lures and live skipjack", "Fighting harness", "Sun protection"], "optional": ["Full-day charter", "Outriggers", "Seasickness tablets"]}'::jsonb, '["Marlin and tuna (Jun-Nov)", "Calm weather windows", "Full moon periods"]'::jsonb, 'Advanced', '["CONAPESCA licence required for everyone aboard", "Daily billfish limits apply; most are tagged and released", "Recreational fishing within 250m of commercial vessels is prohibited"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('magdalena-bay-tuna', 'Magdalena Bay', 'Baja California Sur', 'MX', 'Saltwater', '["yellowfin tuna", "striped marlin", "dolphinfish"]'::jsonb, 'duck-spot', false, 'A vast Pacific bay and mangrove system halfway up Baja, with sardine bait balls offshore each autumn that draw marlin and tuna in spectacular numbers. Snook and grouper inside the mangroves.', '{"lat": 24.6, "lng": -112.1}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Foggy Morning", "temperature": 79, "humidity": 75, "windSpeed": 12, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin outfit for tuna", "Poppers, stickbaits and jigs", "Fluorocarbon leader", "Warm layer for early runs"], "optional": ["Panga charter", "Sounder", "Camera for the bait balls"]}'::jsonb, '["Bait ball season (Oct-Dec)", "Tuna in autumn", "Calm mornings"]'::jsonb, 'Advanced', '["CONAPESCA licence required for all aboard", "Mangrove areas are protected — check where fishing is permitted", "Billfish daily limits apply and release is standard practice"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('campeche-tarpon', 'Campeche Tarpon Flats', 'Campeche', 'MX', 'Saltwater', '["tarpon", "snook", "jack crevalle"]'::jsonb, 'fishing-spot', false, 'Shallow Gulf flats and mangrove creeks holding large numbers of juvenile tarpon in the five to thirty pound range. Ideal water for learning to catch tarpon on fly.', '{"lat": 19.85, "lng": -90.5}'::jsonb, '{"current": 29, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 90, "humidity": 80, "windSpeed": 10, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-9 weight fly rod", "Tarpon toads and baitfish flies", "Shock tippet", "Sun protection"], "optional": ["Panga and guide", "Stripping basket", "Insect repellent"]}'::jsonb, '["Tarpon (Mar-Aug)", "Calm mornings in the creeks", "Rising tide"]'::jsonb, 'Intermediate', '["CONAPESCA licence required when fishing from a boat", "Tarpon are catch-and-release in Mexican sport fishing practice", "Mangrove areas are ecologically protected — follow guide instructions"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('loreto-yellowtail', 'Loreto', 'Baja California Sur', 'MX', 'Saltwater', '["yellowtail", "dolphinfish", "cabrilla"]'::jsonb, 'duck-spot', false, 'A quiet Sea of Cortez town beneath the Sierra de la Giganta, with islands and deep water close inshore. Yellowtail in the cooler months and dorado through the summer.', '{"lat": 26.0, "lng": -111.3}'::jsonb, '{"current": 27, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 95, "humidity": 55, "windSpeed": 8, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin or jigging outfit", "Yo-yo jigs and live bait", "Fluorocarbon leader", "Sun protection"], "optional": ["Panga charter", "Sounder", "Cool box"]}'::jsonb, '["Yellowtail (Jan-Apr)", "Dorado (Jul-Oct)", "Early morning around the islands"]'::jsonb, 'Intermediate', '["CONAPESCA licence required for everyone aboard a vessel", "Loreto Bay National Marine Park has protected zones and gear restrictions", "Daily bag limits apply per species"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('tokyo-bay-seabass', 'Tokyo Bay', 'Tokyo', 'JP', 'Saltwater', '["Japanese sea bass", "yellowtail amberjack", "flathead"]'::jsonb, 'fishing-spot', true, 'Japanese sea bass, or suzuki, hunt the pilings, canal mouths and bridge lights right in the middle of the world''s largest metropolis. Night boats run from central Tokyo and the fishing is genuinely good.', '{"lat": 35.6, "lng": 139.85}'::jsonb, '{"current": 26, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 86, "humidity": 80, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo (8-16lb)", "Minnows, vibration lures and soft plastics", "Fluorocarbon leader", "Head torch"], "optional": ["Charter boat booking", "Landing net", "Rain jacket"]}'::jsonb, '["Summer nights", "Autumn run (Sep-Nov)", "Around the bridge lights on the tide"]'::jsonb, 'Intermediate', '["No licence is required for recreational sea fishing in Japan", "Some port and harbour areas prohibit angling — check posted signs carefully", "Local prefectural rules set minimum sizes for some species"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('nikko-yunoko-trout', 'Lake Yunoko & Nikko', 'Tochigi', 'JP', 'Fly Fishing', '["brook trout", "rainbow trout", "brown trout"]'::jsonb, 'duck-spot', true, 'High mountain lakes and streams in Nikko National Park, stocked with brook and rainbow trout since the Meiji era. Cool alpine water and autumn colour a few hours from Tokyo.', '{"lat": 36.8, "lng": 139.42}'::jsonb, '{"current": 16, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 68, "humidity": 70, "windSpeed": 6, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-5 weight fly rod", "Dry flies and small nymphs", "Waders", "Landing net"], "optional": ["Yugyoken day permit", "Float tube", "Warm layer"]}'::jsonb, '["Season (Apr-Sep)", "Evening rise", "Autumn for colour and fish"]'::jsonb, 'Beginner', '["A yugyoken (day permit) from the local fishing cooperative is required for rivers and lakes", "Permits are sold at tackle shops, convenience stores and increasingly by app", "National park rules restrict access and methods in places"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('nagara-river-ayu', 'Nagara River', 'Gifu', 'JP', 'Freshwater', '["ayu", "Japanese dace", "masu salmon"]'::jsonb, 'fishing-spot', false, 'One of Japan''s last three clear-water rivers, famous for ayu sweetfish and the thousand-year-old tradition of cormorant fishing. Ayu are taken with the unique tomozuri live-decoy method.', '{"lat": 35.45, "lng": 136.77}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 86, "humidity": 75, "windSpeed": 5, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Long tomozuri ayu rod (9-10m)", "Live decoy ayu and tackle", "Wading tights and shoes", "Wading staff"], "optional": ["Cooperative day permit", "Live bait bucket", "Sun protection"]}'::jsonb, '["Ayu season (Jun-Oct)", "Warm summer days", "Clear low water"]'::jsonb, 'Advanced', '["A yugyoken from the Nagara River fishing cooperative is required", "Ayu season dates are set annually by the cooperative and strictly enforced", "Some methods are restricted to protect stocks — check with the cooperative"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-biwa-bass', 'Lake Biwa', 'Shiga', 'JP', 'Freshwater', '["largemouth bass", "Japanese sea bass", "common carp"]'::jsonb, 'duck-spot', false, 'Japan''s largest lake and the source of the world record largemouth bass, caught here in 2009. Weed beds, rock piles and river mouths hold very big fish in clear water.', '{"lat": 35.3, "lng": 136.15}'::jsonb, '{"current": 27, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 88, "humidity": 75, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy baitcast combo", "Big swimbaits, jigs and soft plastics", "Fluorocarbon leader", "Sun protection"], "optional": ["Boat or guide hire", "Sounder", "Polarized sunglasses"]}'::jsonb, '["Pre-spawn (Mar-May)", "Autumn (Oct-Nov)", "Dawn and dusk"]'::jsonb, 'Intermediate', '["A yugyoken permit is required for parts of the lake — check with the local cooperative", "Largemouth bass is a designated invasive species in Japan; releasing it alive is prohibited in Shiga", "Transporting live bass is illegal — know the rules before fishing"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('hokkaido-shiretoko-salmon', 'Shiretoko Peninsula', 'Hokkaido', 'JP', 'Saltwater', '["pink salmon", "chum salmon", "Japanese sea bass"]'::jsonb, 'fishing-spot', false, 'A wild UNESCO-listed peninsula in northeastern Hokkaido where salmon return in vast numbers each autumn. Brown bears fish the same rivers, so shore fishing here demands real care.', '{"lat": 44.1, "lng": 145.1}'::jsonb, '{"current": 16, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 68, "humidity": 80, "windSpeed": 12, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin rod", "Spoons and salmon flies", "Waders", "Bear bell and spray"], "optional": ["Local guide", "Warm layers", "Polarized sunglasses"]}'::jsonb, '["Salmon run (Aug-Oct)", "Dawn from the shore", "After rain"]'::jsonb, 'Intermediate', '["No licence for sea fishing, but river salmon fishing is generally prohibited in Hokkaido", "Salmon may only be taken from the sea or designated areas — river fishing for salmon is illegal", "Brown bears are present; never fish alone and follow park guidance"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('izu-peninsula-offshore', 'Izu Peninsula', 'Shizuoka', 'JP', 'Saltwater', '["yellowtail amberjack", "skipjack tuna", "horse mackerel"]'::jsonb, 'duck-spot', false, 'Deep water and the warm Kuroshio current close inshore south of Tokyo. Rocky headlands for shore jigging, and offshore banks holding yellowtail and tuna.', '{"lat": 34.7, "lng": 138.95}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 84, "humidity": 75, "windSpeed": 10, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or jigging outfit", "Metal jigs and stickbaits", "Studded boots for rock marks", "Buoyancy aid"], "optional": ["Charter boat", "Sounder", "Sun protection"]}'::jsonb, '["Yellowtail (Nov-Feb)", "Tuna in summer", "Dawn from the rocks"]'::jsonb, 'Advanced', '["No licence required for sea fishing in Japan", "Rock fishing here is genuinely hazardous — a lifejacket is expected and often mandatory", "Some harbours and breakwaters ban angling; check local signage"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kushiro-marsh-trout', 'Kushiro Wetlands', 'Hokkaido', 'JP', 'Fly Fishing', '["white-spotted char", "rainbow trout", "masu salmon"]'::jsonb, 'fishing-spot', false, 'Japan''s largest marshland, with slow meandering rivers holding native white-spotted char and big rainbows. Red-crowned cranes nest here, and the landscape feels nothing like the rest of Japan.', '{"lat": 43.1, "lng": 144.4}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Foggy Morning", "temperature": 66, "humidity": 85, "windSpeed": 6, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-6 weight fly rod", "Streamers and terrestrials", "Chest waders", "Insect repellent"], "optional": ["Canoe for the meanders", "Local guide", "Polarized sunglasses"]}'::jsonb, '["Summer (Jun-Sep)", "Early morning mist", "Autumn colour"]'::jsonb, 'Intermediate', '["A yugyoken from the local cooperative is required on most rivers", "National park zones restrict access — stay on designated routes", "Salmon may not be taken from rivers in Hokkaido"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('okinawa-gt', 'Okinawa Reefs', 'Okinawa', 'JP', 'Saltwater', '["giant trevally", "dogtooth tuna", "coral trout"]'::jsonb, 'duck-spot', false, 'Subtropical coral reefs and steep drop-offs in the East China Sea. Giant trevally smash poppers on the reef edges, with dogtooth tuna holding deeper on the pinnacles.', '{"lat": 26.3, "lng": 127.8}'::jsonb, '{"current": 29, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 88, "humidity": 80, "windSpeed": 12, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy popping outfit (PE8-10)", "Poppers and stickbaits", "Reef-safe sunscreen", "Heavy fluorocarbon leader"], "optional": ["Charter booking", "Fighting belt", "Polarized sunglasses"]}'::jsonb, '["GT (Apr-Oct)", "Dawn on the reef edge", "Typhoon-free weather windows"]'::jsonb, 'Advanced', '["No licence needed for recreational sea fishing", "Coral reef protection rules apply — anchoring and some methods are restricted", "Typhoon season runs roughly June to October; check forecasts"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kurobe-river-iwana', 'Kurobe River', 'Toyama', 'JP', 'Fly Fishing', '["white-spotted char", "masu salmon", "Japanese dace"]'::jsonb, 'fishing-spot', false, 'A steep alpine river cutting through a deep gorge in the Northern Japan Alps. Native iwana char hold in the pocket water, in some of the most dramatic scenery in the country.', '{"lat": 36.6, "lng": 137.6}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 72, "humidity": 70, "windSpeed": 5, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["3-5 weight fly rod or tenkara rod", "Dry flies and small nymphs", "Wading boots with studs", "Wading staff"], "optional": ["Cooperative day permit", "Bear bell", "Hiking gear"]}'::jsonb, '["Season (Mar-Sep)", "Summer in the upper gorge", "Evening rise"]'::jsonb, 'Advanced', '["A yugyoken from the local cooperative is required", "Season dates are set by the cooperative, typically March to September", "Steep terrain and sudden dam releases make this river genuinely dangerous — check schedules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ariake-sea-flats', 'Ariake Sea', 'Kyushu', 'JP', 'Saltwater', '["Japanese sea bass", "mullet", "flathead"]'::jsonb, 'duck-spot', false, 'A large shallow inland sea on Kyushu with Japan''s biggest tidal range, exposing vast mudflats twice a day. Sea bass hunt the tidal creeks and channel edges as the water floods back.', '{"lat": 33.0, "lng": 130.3}'::jsonb, '{"current": 27, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 86, "humidity": 80, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Vibration lures and minnows", "Waders", "Head torch"], "optional": ["Small boat or kayak", "Tide tables", "Insect repellent"]}'::jsonb, '["Sea bass in spring and autumn", "Flooding tide", "Night fishing"]'::jsonb, 'Intermediate', '["No licence needed for sea fishing", "Tidal flats here are dangerous — the tide moves faster than you can walk", "Seaweed farms and fishing rights areas are off limits; check locally"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kola-peninsula-salmon', 'Kola Peninsula Rivers', 'Murmansk Oblast', 'RU', 'Fly Fishing', '["Atlantic salmon", "brown trout", "Arctic char"]'::jsonb, 'fishing-spot', true, 'Tundra rivers on the Kola Peninsula hold the strongest remaining runs of wild Atlantic salmon in the world. Big fish in remote, treeless country under the midnight sun.', '{"lat": 68.0, "lng": 36.0}'::jsonb, '{"current": 10, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 57, "humidity": 75, "windSpeed": 12, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["13-15ft Spey rod", "Tube flies and sink tips", "Chest waders", "Insect repellent"], "optional": ["Lodge package with helicopter access", "Head net", "Windproof layers"]}'::jsonb, '["Peak run (Jun-Jul)", "Midnight sun", "After a rise in water"]'::jsonb, 'Advanced', '["No general licence is needed for recreational fishing in Russia, but salmon rivers are premium waters requiring a specific permit", "Kola salmon rivers are managed by licensed camps and access is by permit only", "Border zone permits may be required near the Norwegian and Finnish frontiers"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kamchatka-rainbow-trout', 'Kamchatka Rivers', 'Kamchatka Krai', 'RU', 'Fly Fishing', '["rainbow trout", "king salmon", "char"]'::jsonb, 'duck-spot', true, 'Volcanic wilderness on the Pacific rim with rivers holding wild rainbow trout and all five Pacific salmon species. Brown bears outnumber anglers by a wide margin.', '{"lat": 56.0, "lng": 159.0}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 59, "humidity": 75, "windSpeed": 10, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-8 weight fly rod", "Mouse patterns and streamers", "Chest waders", "Bear spray"], "optional": ["Helicopter or raft expedition", "Guide — essential here", "Insect repellent"]}'::jsonb, '["Rainbow season (Jul-Sep)", "Mouse fishing in late summer", "Salmon runs from June"]'::jsonb, 'Advanced', '["Recreational fishing is generally unlicensed, but premium salmon and trout rivers require permits", "Kamchatka has border and protected-area restrictions requiring advance paperwork", "Most rivers are accessible only through licensed outfitters"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('volga-delta-catfish', 'Volga Delta', 'Astrakhan Oblast', 'RU', 'Freshwater', '["wels catfish", "zander", "asp"]'::jsonb, 'fishing-spot', false, 'Where Europe''s longest river fans out into the Caspian Sea across a maze of channels and reed beds. Enormous wels catfish and prolific zander fishing in a famous angling region.', '{"lat": 46.0, "lng": 48.3}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 90, "humidity": 55, "windSpeed": 10, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy catfish rod", "Clonk, large softbaits and deadbaits", "Braided line and heavy leader", "Sun protection"], "optional": ["Boat and local guide", "Insect repellent", "Cool box"]}'::jsonb, '["Summer (Jun-Sep)", "Spring after the flood", "Dawn and dusk"]'::jsonb, 'Intermediate', '["No general recreational licence is required in Russia", "Sturgeon are strictly protected — targeting or keeping them is a serious offence", "Some delta channels are within protected reserves and closed to angling"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-baikal-omul', 'Lake Baikal', 'Irkutsk Oblast / Buryatia', 'RU', 'Freshwater', '["omul", "grayling", "taimen"]'::jsonb, 'duck-spot', false, 'The oldest and deepest lake on earth, holding a fifth of the world''s unfrozen fresh water and species found nowhere else. Grayling along the shore and ice fishing in a spectacular winter setting.', '{"lat": 53.5, "lng": 108.0}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 64, "humidity": 60, "windSpeed": 10, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Light spin or fly rod", "Small spoons and nymphs", "Warm layers", "Landing net"], "optional": ["Local guide or boat", "Ice gear in winter", "Polarized sunglasses"]}'::jsonb, '["Summer grayling (Jun-Aug)", "Ice fishing (Feb-Mar)", "Calm mornings"]'::jsonb, 'Intermediate', '["Recreational fishing is generally unlicensed but Baikal has specific protections", "Omul has been subject to catch bans to allow stocks to recover — check current status", "Large parts of the shoreline are within national parks with fishing restrictions"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ponoi-river', 'Ponoi River', 'Murmansk Oblast', 'RU', 'Fly Fishing', '["Atlantic salmon"]'::jsonb, 'fishing-spot', false, 'The largest river on the Kola Peninsula and arguably the most productive Atlantic salmon fishery in the world by numbers. Long gentle runs ideal for the swung fly.', '{"lat": 67.1, "lng": 41.1}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 57, "humidity": 75, "windSpeed": 12, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["12-14ft Spey rod", "Small tubes and riffle hitch flies", "Chest waders", "Insect repellent"], "optional": ["Camp package with guide", "Head net", "Waterproof layers"]}'::jsonb, '["Spring run (Jun)", "Autumn run (Sep)", "Steady water levels"]'::jsonb, 'Advanced', '["Access is exclusively through licensed camps holding the river permits", "Catch-and-release is standard on the Ponoi", "Foreign anglers need border zone documentation for parts of the Kola"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lena-river-taimen', 'Lena River Basin', 'Sakha Republic', 'RU', 'Freshwater', '["taimen", "lenok", "grayling"]'::jsonb, 'duck-spot', false, 'Siberian wilderness rivers holding taimen, the world''s largest salmonid, which can exceed a metre and a half. Expedition fishing with very long approaches and short seasons.', '{"lat": 62.0, "lng": 129.7}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 68, "humidity": 60, "windSpeed": 8, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-10 weight fly rod or heavy spin", "Large mouse patterns and streamers", "Chest waders", "Insect repellent"], "optional": ["Full expedition outfitter", "Satellite communicator", "Camping gear"]}'::jsonb, '["Late summer (Aug-Sep)", "Mouse fishing at dusk", "Low clear water"]'::jsonb, 'Advanced', '["Taimen are protected in many Russian regions and are strictly catch-and-release", "Expedition permits and regional paperwork are required — go through an outfitter", "Extremely remote; there is no infrastructure or rescue capability"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('black-sea-coast-russia', 'Black Sea Coast', 'Krasnodar Krai', 'RU', 'Saltwater', '["horse mackerel", "bluefish", "mullet"]'::jsonb, 'fishing-spot', false, 'The Caucasus coast between Sochi and Novorossiysk, with deep water close to shore and easy pier and rock fishing. Horse mackerel and bluefish shoal through the warm months.', '{"lat": 44.3, "lng": 38.5}'::jsonb, '{"current": 24, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 84, "humidity": 70, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Light spin rod", "Sabiki rigs and small metals", "Landing net", "Sun protection"], "optional": ["Boat trip", "Head torch for night fishing", "Cool box"]}'::jsonb, '["Summer and autumn", "Bluefish (Sep-Nov)", "Evening from the piers"]'::jsonb, 'Beginner', '["No general licence is required for recreational sea fishing", "Some port and resort areas restrict angling — check local signage", "Size and bag limits apply to certain species under Azov-Black Sea basin rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('karelia-lakes-pike', 'Karelian Lakes', 'Republic of Karelia', 'RU', 'Freshwater', '["northern pike", "perch", "brown trout"]'::jsonb, 'duck-spot', false, 'Thousands of forest lakes and rivers between Lake Ladoga and the White Sea. Big pike in shallow reedy bays with almost no fishing pressure outside the main tourist areas.', '{"lat": 62.0, "lng": 33.5}'::jsonb, '{"current": 19, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 68, "humidity": 75, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo", "Softbaits, spinnerbaits and wire traces", "Unhooking mat", "Insect repellent"], "optional": ["Boat or cottage rental", "Sounder", "Waterproof clothing"]}'::jsonb, '["Summer (Jun-Aug)", "Autumn pike", "Ice fishing (Feb-Mar)"]'::jsonb, 'Beginner', '["Recreational angling is generally free and unlicensed", "Some lakes are leased to operators and require a day ticket", "Border zone permits are needed close to the Finnish frontier"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-ladoga-salmon', 'Lake Ladoga', 'Leningrad Oblast', 'RU', 'Freshwater', '["landlocked salmon", "lake trout", "pike"]'::jsonb, 'fishing-spot', false, 'Europe''s largest lake, big enough to generate its own weather and holding a landlocked Atlantic salmon population. Trolling the open water and fishing the skerries in the north.', '{"lat": 60.9, "lng": 31.5}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 68, "humidity": 75, "windSpeed": 16, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Trolling or heavy spin outfit", "Spoons and deep divers", "Sounder", "Waterproof clothing"], "optional": ["Boat with reliable motor", "Downrigger", "Life jacket — the lake gets very rough"]}'::jsonb, '["Spring salmon trolling", "Autumn pike in the skerries", "Calm weather windows"]'::jsonb, 'Intermediate', '["No general recreational fishing licence is required", "Landlocked salmon are protected with seasonal restrictions — check regional rules", "Conditions change fast on open water; the lake has claimed many small boats"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('amur-river-kaluga', 'Amur River', 'Khabarovsk Krai', 'RU', 'Freshwater', '["taimen", "Amur pike", "lenok"]'::jsonb, 'duck-spot', false, 'A vast Far Eastern river forming much of the Chinese border, holding a distinctive fauna including Amur pike and taimen. Big, remote water with a short open-water season.', '{"lat": 48.5, "lng": 135.1}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 77, "humidity": 70, "windSpeed": 8, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or 9-weight fly rod", "Large streamers and spoons", "Waders", "Insect repellent"], "optional": ["Boat and local guide", "Camping gear", "Satellite communicator"]}'::jsonb, '["Late summer (Aug-Sep)", "Before the autumn freeze", "Low clear water"]'::jsonb, 'Advanced', '["Taimen and kaluga sturgeon are protected — sturgeon may not be targeted at all", "Border river: crossing towards the Chinese bank is prohibited and permits may be needed", "Use a licensed local outfitter familiar with the border rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('masurian-lakes-pike', 'Masurian Lake District', 'Warmia-Masuria', 'PL', 'Freshwater', '["northern pike", "zander", "perch"]'::jsonb, 'fishing-spot', true, 'Two thousand connected lakes in northeastern Poland, a landscape of reed beds, forest and quiet water. Excellent pike and zander fishing with an established angling tourism scene.', '{"lat": 53.8, "lng": 21.6}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 73, "humidity": 70, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo", "Softbaits, jerkbaits and wire traces", "Unhooking mat", "Landing net"], "optional": ["Boat hire", "Sounder", "Insect repellent"]}'::jsonb, '["Autumn pike (Sep-Nov)", "Zander at dusk", "Ice fishing (Jan-Feb)"]'::jsonb, 'Beginner', '["Polish nationals need a karta wędkarska (fishing card) obtained by exam — foreign visitors are exempt", "A zezwolenie (permit) for the specific water is always required, usually from PZW", "Pike and zander have closed seasons and minimum sizes"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('vistula-river-zander', 'River Vistula', 'Mazovia', 'PL', 'Freshwater', '["zander", "wels catfish", "asp"]'::jsonb, 'duck-spot', true, 'Poland''s great river, largely unregulated and braided with sandbanks as it runs past Warsaw. Zander and asp hunt the current seams, with large catfish in the deeper holes.', '{"lat": 52.25, "lng": 21.0}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 77, "humidity": 60, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin rod", "Softbaits and jigheads", "Waders", "Fluorocarbon leader"], "optional": ["Boat for the sandbanks", "Head torch", "Polarized sunglasses"]}'::jsonb, '["Zander at dusk", "Asp in summer", "Autumn feeding"]'::jsonb, 'Intermediate', '["Foreign visitors are exempt from the karta wędkarska requirement", "A PZW permit for the relevant district is required", "Zander and asp have closed seasons and size limits"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('drawa-river-trout', 'River Drawa', 'West Pomerania', 'PL', 'Fly Fishing', '["brown trout", "grayling", "sea trout"]'::jsonb, 'fishing-spot', false, 'A clear lowland river winding through the Drawa National Park forest, holding wild brown trout and grayling. Fly-only management on much of the water keeps it in good condition.', '{"lat": 53.1, "lng": 15.9}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 70, "humidity": 75, "windSpeed": 6, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-5 weight fly rod", "Dry flies and nymphs", "Chest waders", "Polarized sunglasses"], "optional": ["National park permit", "Canoe for access", "Wading staff"]}'::jsonb, '["Summer evenings", "Grayling in autumn", "After rain"]'::jsonb, 'Intermediate', '["Visitors are exempt from the karta wędkarska but need a water permit", "Drawa National Park has its own permit and restricted zones", "Fly-only and no-kill rules apply on much of the river"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('baltic-coast-sea-trout', 'Polish Baltic Coast', 'Pomerania', 'PL', 'Saltwater', '["sea trout", "cod", "flounder"]'::jsonb, 'duck-spot', false, 'Long sand beaches and shallow bars along the Polish Baltic, with sea trout patrolling close inshore. Best in the cold months when few anglers are on the beach.', '{"lat": 54.5, "lng": 17.5}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 68, "humidity": 80, "windSpeed": 16, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft spin rod", "Coastal spoons and shrimp flies", "Breathable chest waders", "Windproof jacket"], "optional": ["Line basket for fly", "Wading staff", "Thermal layers"]}'::jsonb, '["Sea trout (Oct-Apr)", "Onshore wind", "Dawn and dusk"]'::jsonb, 'Intermediate', '["A sea fishing permit is required and is inexpensive — available weekly or annually", "Sea trout minimum size applies and coloured spawning fish must be released", "Cod limits in the Baltic are set annually by EU rules — check before keeping fish"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('san-river-grayling', 'River San', 'Subcarpathia', 'PL', 'Fly Fishing', '["grayling", "brown trout", "rainbow trout"]'::jsonb, 'fishing-spot', false, 'A tailwater below the Solina dam in southeastern Poland, running cold and clear year-round. Regarded as the country''s finest grayling river and fishable even in deep winter.', '{"lat": 49.4, "lng": 22.4}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 72, "humidity": 65, "windSpeed": 6, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["3-5 weight fly rod", "Small dries and Euro-nymph rigs", "Chest waders with studs", "Fine tippet"], "optional": ["Regional permit", "Wading staff", "Warm layers for winter"]}'::jsonb, '["Grayling (Sep-Dec)", "Winter nymphing", "Summer evening rise"]'::jsonb, 'Advanced', '["Visitors are exempt from the karta wędkarska but need the appropriate PZW permit", "Much of the river is no-kill with barbless hooks", "Dam releases can change levels quickly — check before wading"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('solina-lake', 'Lake Solina', 'Subcarpathia', 'PL', 'Freshwater', '["northern pike", "zander", "common carp"]'::jsonb, 'duck-spot', false, 'Poland''s largest reservoir, set in the Bieszczady mountains with clear deep water and steep wooded shores. Pike and zander in a landscape closer to the Alps than the Polish plain.', '{"lat": 49.4, "lng": 22.45}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 72, "humidity": 65, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Softbaits and deep-diving lures", "Sounder", "Landing net"], "optional": ["Boat hire", "Polarized sunglasses", "Rain jacket"]}'::jsonb, '["Autumn pike", "Summer zander at depth", "Early morning"]'::jsonb, 'Beginner', '["A PZW permit for Lake Solina is required", "Closed seasons and minimum sizes apply to pike and zander", "Boat and motor restrictions apply on parts of the reservoir"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('oder-river-asp', 'River Oder', 'Lubusz', 'PL', 'Freshwater', '["asp", "zander", "wels catfish"]'::jsonb, 'fishing-spot', false, 'The German border river, wide and slow with long groyne fields that concentrate baitfish. Asp smash surface lures in the current seams through the summer.', '{"lat": 52.3, "lng": 14.6}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 79, "humidity": 60, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin rod", "Surface lures, spinners and softbaits", "Polarized sunglasses", "Landing net"], "optional": ["Boat for the groyne fields", "Waders", "Sun protection"]}'::jsonb, '["Asp in summer", "Zander at dusk", "Autumn catfish"]'::jsonb, 'Intermediate', '["Visitors are exempt from the karta wędkarska but need a district permit", "This is a border river — do not cross into German water without a German permit", "Asp and zander have closed seasons and minimum sizes"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('dunajec-river-trout', 'River Dunajec', 'Lesser Poland', 'PL', 'Fly Fishing', '["brown trout", "grayling", "huchen"]'::jsonb, 'duck-spot', false, 'A mountain river running out of the Tatras through the Pieniny gorge, famous for its raft trips and its huchen. Fast, clean water with good trout and grayling throughout.', '{"lat": 49.42, "lng": 20.35}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 72, "humidity": 70, "windSpeed": 6, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-6 weight fly rod", "Nymphs and dry flies", "Chest waders with studs", "Wading staff"], "optional": ["Regional permit", "Polarized sunglasses", "Rain jacket"]}'::jsonb, '["Summer and autumn", "Grayling (Sep-Nov)", "After rain settles"]'::jsonb, 'Intermediate', '["PZW or local permit required; visitors are exempt from the karta wędkarska", "Huchen is strictly protected with a very limited season and permit", "National park sections have additional restrictions"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('szczecin-lagoon', 'Szczecin Lagoon', 'West Pomerania', 'PL', 'Freshwater', '["zander", "northern pike", "bream"]'::jsonb, 'fishing-spot', false, 'A vast brackish lagoon shared with Germany at the mouth of the Oder. Shallow and coloured, it produces very large zander and pike, particularly in autumn.', '{"lat": 53.75, "lng": 14.4}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 73, "humidity": 75, "windSpeed": 16, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo", "Softbaits and vertical jigs", "Sounder", "Landing net"], "optional": ["Boat with a reliable motor", "Waterproof clothing", "Head torch"]}'::jsonb, '["Autumn zander (Sep-Nov)", "Winter pike", "Calm days — it gets rough fast"]'::jsonb, 'Intermediate', '["A Polish permit is required; the German side needs a separate permit", "Zander and pike closed seasons and minimum sizes apply", "The lagoon is shallow and exposed — check the forecast before going out"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('raba-river-trout', 'River Raba', 'Lesser Poland', 'PL', 'Fly Fishing', '["brown trout", "grayling"]'::jsonb, 'duck-spot', false, 'A Carpathian foothill river south of Kraków with a well-managed no-kill section. Accessible wild trout and grayling fishing within an hour of the city.', '{"lat": 49.8, "lng": 20.1}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 73, "humidity": 65, "windSpeed": 6, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["3-5 weight fly rod", "Nymphs and small dries", "Chest waders", "Polarized sunglasses"], "optional": ["Local permit", "Wading staff", "Landing net"]}'::jsonb, '["Spring and autumn", "Summer evening rise", "After rain clears"]'::jsonb, 'Intermediate', '["Visitors are exempt from the karta wędkarska but need the local permit", "No-kill sections require barbless hooks", "Closed seasons apply to trout and grayling"]'::jsonb);
